// Package calendar writes reminders as iCalendar (RFC 5545) files that
// calendar apps can import or subscribe to.
package calendar

import (
	"fmt"
	"io"
	"strings"
	"time"
	"unicode/utf8"
)

// maxLine is the longest content line, in octets, before it is folded.
const maxLine = 75

// utcFormat is the iCalendar form of a UTC date-time.
const utcFormat = "20060102T150405Z"

// An Event is one calendar entry.
type Event struct {
	UID         string
	Summary     string
	Description string
	Start       time.Time
	Duration    time.Duration
	RRule       string // a recurrence rule such as "FREQ=DAILY", or empty
}

// A Writer writes calendars. The zero value stamps events with the
// current time.
type Writer struct {
	Now func() time.Time // the DTSTAMP clock; nil means time.Now
}

// Write writes events as a calendar, using the current time as each
// event's DTSTAMP.
func Write(w io.Writer, prodID string, events []Event) error {
	return Writer{}.Write(w, prodID, events)
}

// Write writes events to w as a VCALENDAR identified by prodID.
// Every event needs a UID and a start time.
func (cw Writer) Write(w io.Writer, prodID string, events []Event) error {
	now := time.Now
	if cw.Now != nil {
		now = cw.Now
	}
	stamp := now().UTC().Format(utcFormat)

	var b strings.Builder
	line(&b, "BEGIN:VCALENDAR")
	line(&b, "VERSION:2.0")
	line(&b, "PRODID:"+escape(prodID))
	line(&b, "CALSCALE:GREGORIAN")
	for i, e := range events {
		if e.UID == "" {
			return fmt.Errorf("calendar: event %d has no UID", i)
		}
		if e.Start.IsZero() {
			return fmt.Errorf("calendar: event %s has no start time", e.UID)
		}
		line(&b, "BEGIN:VEVENT")
		line(&b, "UID:"+escape(e.UID))
		line(&b, "DTSTAMP:"+stamp)
		line(&b, "DTSTART:"+e.Start.UTC().Format(utcFormat))
		line(&b, "DURATION:"+formatDuration(e.Duration))
		if e.RRule != "" {
			line(&b, "RRULE:"+e.RRule)
		}
		line(&b, "SUMMARY:"+escape(e.Summary))
		if e.Description != "" {
			line(&b, "DESCRIPTION:"+escape(e.Description))
		}
		line(&b, "END:VEVENT")
	}
	line(&b, "END:VCALENDAR")

	if _, err := io.WriteString(w, b.String()); err != nil {
		return fmt.Errorf("write calendar: %w", err)
	}
	return nil
}

// line writes one content line, folding it into lines of at most
// maxLine octets. Continuation lines start with a space.
func line(b *strings.Builder, s string) {
	limit := maxLine
	for len(s) > limit {
		cut := limit
		for !utf8.RuneStart(s[cut]) {
			cut--
		}
		b.WriteString(s[:cut])
		b.WriteString("\r\n ")
		s = s[cut:]
		limit = maxLine - 1
	}
	b.WriteString(s)
	b.WriteString("\r\n")
}

var textEscaper = strings.NewReplacer(
	`\`, `\\`,
	";", `\;`,
	",", `\,`,
	"\r\n", `\n`,
	"\n", `\n`,
	"\r", `\n`,
)

// escape escapes a TEXT property value.
func escape(s string) string {
	return textEscaper.Replace(s)
}

// formatDuration formats d as an iCalendar duration such as "PT15M" or
// "P1DT2H". Fractions of a second are dropped.
func formatDuration(d time.Duration) string {
	var b strings.Builder
	if d < 0 {
		b.WriteByte('-')
		d = -d
	}
	b.WriteByte('P')
	secs := int64(d / time.Second)
	days := secs / 86400
	parts := [3]int64{secs % 86400 / 3600, secs % 3600 / 60, secs % 60}
	if days > 0 {
		fmt.Fprintf(&b, "%dD", days)
	}

	// RFC 5545 doesn't allow gaps (hours then seconds without minutes),
	// so write every unit from the first nonzero one to the last.
	first, last := -1, -1
	for i, p := range parts {
		if p != 0 {
			if first < 0 {
				first = i
			}
			last = i
		}
	}
	if first < 0 {
		if days == 0 {
			b.WriteString("T0S")
		}
		return b.String()
	}
	b.WriteByte('T')
	for i := first; i <= last; i++ {
		fmt.Fprintf(&b, "%d%c", parts[i], "HMS"[i])
	}
	return b.String()
}

// Package notify delivers reminders through each user's chosen channel.
package notify

import (
	"context"
	"encoding/json"
	"fmt"
	"log/slog"
	"maps"
	"slices"
	"sync"
	"time"

	"example.com/remind/i18n"
	"example.com/remind/store"
	"example.com/remind/webhook"
)

// A Message is one notification.
type Message struct {
	To      *store.User
	Subject string
	Body    string
}

// A Sender delivers messages over one channel.
type Sender interface {
	Send(ctx context.Context, m Message) error
}

// channels lists the channel names users may choose.
var channels = []string{"email", "webhook", "sms"}

// ValidChannel reports whether name is a channel users may choose.
func ValidChannel(name string) bool {
	return slices.Contains(channels, name)
}

// Dispatcher sends due reminders.
type Dispatcher struct {
	store   *store.Store
	senders map[string]Sender
	log     *slog.Logger
	now     func() time.Time

	mu      sync.Mutex
	retries map[string]int // failed sends per reminder ID
	stop    chan struct{}
}

// NewDispatcher returns a dispatcher with the email and webhook channels.
func NewDispatcher(s *store.Store, log *slog.Logger, now func() time.Time) *Dispatcher {
	d := &Dispatcher{
		store: s,
		senders: map[string]Sender{
			"email":   emailSender{log: log},
			"webhook": webhookSender{client: &webhook.Client{Log: log, Now: now}, now: now},
		},
		log:     log,
		now:     now,
		retries: make(map[string]int),
		stop:    make(chan struct{}),
	}
	s.OnChange(d.forget)
	return d
}

// SetWebhookSecret sets the key webhook deliveries are signed with.
func (d *Dispatcher) SetWebhookSecret(secret []byte) {
	d.senders["webhook"].(webhookSender).client.Secret = secret
}

// Status is what the admin dashboard shows about deliveries.
type Status struct {
	Retrying int      `json:"retrying"` // reminders whose last send failed
	Channels []string `json:"channels"`
}

// Status reports the dispatcher's current state.
func (d *Dispatcher) Status() Status {
	return Status{Retrying: len(d.retries), Channels: slices.Sorted(maps.Keys(d.senders))}
}

// Run sends due reminders every interval until Stop is called or ctx
// ends.
func (d *Dispatcher) Run(ctx context.Context, interval time.Duration) {
	t := time.NewTicker(interval)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-d.stop:
			return
		case <-t.C:
			d.flush(ctx)
		}
	}
}

// Stop stops Run.
func (d *Dispatcher) Stop() {
	close(d.stop)
}

// flush sends every due reminder once. It holds d.mu so flushes never
// overlap.
func (d *Dispatcher) flush(ctx context.Context) {
	d.mu.Lock()
	defer d.mu.Unlock()
	for _, r := range d.store.Due(d.now()) {
		u, err := d.store.User(r.UserID)
		if err != nil {
			continue
		}
		if err := d.SendNow(ctx, u, r); err != nil {
			d.retries[r.ID]++
			d.log.Warn("notify: send failed", "reminder", r.ID, "attempt", d.retries[r.ID], "err", err)
			continue
		}
		delete(d.retries, r.ID)
		d.store.MarkSent(r.ID)
	}
}

// forget drops retry state for a reminder that changed.
func (d *Dispatcher) forget(r *store.Reminder) {
	d.mu.Lock()
	defer d.mu.Unlock()
	delete(d.retries, r.ID)
}

// SendNow sends one reminder to its user immediately.
func (d *Dispatcher) SendNow(ctx context.Context, u *store.User, r *store.Reminder) error {
	if err := d.senders[u.Prefs.Channel].Send(ctx, message(u, r)); err != nil {
		return fmt.Errorf("send %s: %w", r.ID, err)
	}
	return nil
}

// message renders a reminder in the user's language.
func message(u *store.User, r *store.Reminder) Message {
	lang := u.Prefs.Lang
	return Message{
		To:      u,
		Subject: i18n.Translate(lang, "reminder.subject", 0, map[string]string{"text": Preview(r.Text)}),
		Body:    i18n.Translate(lang, "reminder.body", 0, map[string]string{"name": u.Name, "text": r.Text}),
	}
}

type emailSender struct {
	log *slog.Logger
}

func (s emailSender) Send(_ context.Context, m Message) error {
	// The mail relay picks messages up from the log stream.
	s.log.Info("notify: email queued", "to", m.To.Email, "subject", m.Subject)
	return nil
}

type webhookSender struct {
	client *webhook.Client
	now    func() time.Time
}

func (s webhookSender) Send(ctx context.Context, m Message) error {
	body, err := json.Marshal(map[string]string{"subject": m.Subject, "body": m.Body})
	if err != nil {
		return fmt.Errorf("webhook: %w", err)
	}
	d := &webhook.Delivery{
		ID:      fmt.Sprintf("whd_%d", s.now().UnixNano()),
		URL:     m.To.Prefs.Webhook,
		Event:   "reminder.due",
		Payload: body,
		Created: s.now(),
	}
	if err := s.client.Post(ctx, d); err != nil {
		return fmt.Errorf("webhook to %s: %w", d.URL, err)
	}
	return nil
}

package api

import (
	"net/http"
	"strconv"
	"time"

	"example.com/remind/auth"
	"example.com/remind/calendar"
	"example.com/remind/schedule"
)

func (a *API) search(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFrom(r.Context())
	q := r.URL.Query().Get("q")
	if q == "" {
		a.fail(w, http.StatusBadRequest, "q is required")
		return
	}
	limit := 20
	if s := r.URL.Query().Get("limit"); s != "" {
		n, err := strconv.Atoi(s)
		if err != nil || n < 1 || n > 100 {
			a.fail(w, http.StatusBadRequest, "limit must be between 1 and 100")
			return
		}
		limit = n
	}
	var views []reminderView
	for _, hit := range a.Search.Search(u.ID, q, limit) {
		rem, err := a.Store.Get(hit.DocID)
		if err != nil {
			continue
		}
		views = append(views, viewOf(rem))
	}
	a.writeJSON(w, http.StatusOK, map[string]any{"reminders": views})
}

// calendarFeed serves the caller's reminders as an iCalendar file that
// calendar apps can subscribe to.
func (a *API) calendarFeed(w http.ResponseWriter, r *http.Request) {
	u := auth.UserFrom(r.Context())
	var events []calendar.Event
	for _, rem := range a.Store.List(u.ID, 0, 1000) {
		if rem.Done {
			continue
		}
		ev := calendar.Event{
			UID:      rem.ID + "@remind.example",
			Summary:  rem.Text,
			Start:    rem.Due,
			Duration: 15 * time.Minute,
		}
		switch rule := rem.Rule.(type) {
		case schedule.Weekly:
			ev.RRule = calendar.WeeklyRRule(rule.Days)
		case schedule.Every:
			ev.RRule = calendar.IntervalRRule(rule.Interval)
		}
		events = append(events, ev)
	}
	w.Header().Set("Content-Type", "text/calendar; charset=utf-8")
	cw := calendar.Writer{Now: a.Now}
	if err := cw.Write(w, "-//remind//reminders//EN", events); err != nil {
		a.Log.Warn("write calendar", "user", u.ID, "err", err)
	}
}

